// Breadboard Bench service worker (generated by tools/build_sw.py — edit tools/sw_template.js).
// Everything the app needs is cached on the first visit, so it then runs with no network.
// App files are fetched fresh when online (so updates arrive) and from the cache when offline;
// the large Pyodide files and fonts are always served from the cache once stored.
const VERSION = "23e4217d134e";
const CACHE = `bbench-${VERSION}`;
const FILES = [
 "./",
 "LICENSE",
 "engine.js",
 "engine_glue.py",
 "engine_mock.js",
 "engine_worker.js",
 "index.html",
 "manifest.json",
 "LICENSES/Breadboard-Bench-MIT.txt",
 "LICENSES/CPython-3.14-LICENSE.txt",
 "LICENSES/Emscripten-LICENSE.txt",
 "LICENSES/OFL-Fredoka.txt",
 "LICENSES/OFL-JetBrainsMono.txt",
 "LICENSES/OFL-Lexend.txt",
 "LICENSES/Pyodide-MPL-2.0.txt",
 "LICENSES/index.html",
 "css/app.css",
 "fonts/README.txt",
 "fonts/fredoka-latin-500-normal.woff2",
 "fonts/fredoka-latin-600-normal.woff2",
 "fonts/fredoka-latin-700-normal.woff2",
 "fonts/jetbrains-mono-latin-400-italic.woff2",
 "fonts/jetbrains-mono-latin-400-normal.woff2",
 "fonts/jetbrains-mono-latin-700-normal.woff2",
 "fonts/lexend-latin-300-normal.woff2",
 "fonts/lexend-latin-400-normal.woff2",
 "fonts/lexend-latin-500-normal.woff2",
 "fonts/lexend-latin-600-normal.woff2",
 "fonts/lexend-latin-700-normal.woff2",
 "icons/icon-192.png",
 "icons/icon-512.png",
 "icons/icon.svg",
 "js/analyser.js",
 "js/app.js",
 "js/bbgeom.js",
 "js/breadboard.js",
 "js/clockctl.js",
 "js/code.js",
 "js/examples.js",
 "js/frontpanel.js",
 "js/functables.js",
 "js/library.js",
 "js/parts.js",
 "js/pc2asm.js",
 "js/schematic.js",
 "js/signals.js",
 "js/simctl.js",
 "js/store.js",
 "js/ui.js",
 "js/util.js",
 "js/viewport.js",
 "js/where.js",
 "mock/chips.json",
 "mock/pc2.bbproj",
 "py/bbench-1.0.0-py3-none-any.whl",
 "py/index.json",
 "pyodide/README.txt",
 "pyodide/package.json",
 "pyodide/pyodide-lock.json",
 "pyodide/pyodide.asm.mjs",
 "pyodide/pyodide.asm.wasm",
 "pyodide/pyodide.mjs",
 "pyodide/python_stdlib.zip"
];

self.addEventListener("install", (e) => {
  e.waitUntil((async () => {
    const c = await caches.open(CACHE);
    // one by one, so a single missing file does not stop the rest
    await Promise.all(FILES.map((f) => c.add(new Request(f, { cache: "reload" })).catch(() => null)));
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", (e) => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith("bbench-") && k !== CACHE) await caches.delete(k);
    await self.clients.claim();
  })());
});

const STATIC = /\/(pyodide|fonts|icons)\//;

self.addEventListener("fetch", (e) => {
  const req = e.request;
  if (req.method !== "GET" || new URL(req.url).origin !== location.origin) return;
  e.respondWith((async () => {
    const c = await caches.open(CACHE);
    if (STATIC.test(new URL(req.url).pathname)) {
      const hit = await c.match(req, { ignoreSearch: true });
      if (hit) return hit;
      const r = await fetch(req);
      if (r.ok) c.put(req, r.clone());
      return r;
    }
    try {
      const r = await fetch(req);
      if (r.ok) c.put(req, r.clone());
      return r;
    } catch (err) {
      const hit = await c.match(req, { ignoreSearch: true });
      if (hit) return hit;
      if (req.mode === "navigate") { const home = await c.match("./"); if (home) return home; }
      throw err;
    }
  })());
});
